"""Pure functions of Revising Densification (arXiv 2404.06109), CPU-testable."""

import math

import torch
import torch.nn.functional as F

# Global primitive cap (Sec. 4.2: "the number of primitives generated by the corresponding
# baseline"). Our baseline is runs/baseline3dgs-<dataset>-30000 (gsplat, 3DGS recipe, opacity
# reset). Keyed by the number of SfM points the 3DGS recipe initialises from
# (--num-gaussians 10000000 keeps all of them), which is unique for the 13 benchmark scenes.
BASELINE_CAP = {
    54275: ("mipnerf360/bicycle", 6590201),
    206613: ("mipnerf360/bonsai", 1373997),
    155767: ("mipnerf360/counter", 1215973),
    38347: ("mipnerf360/flowers", 3857839),
    138766: ("mipnerf360/garden", 4764685),
    241367: ("mipnerf360/kitchen", 1416375),
    112627: ("mipnerf360/room", 1727096),
    32049: ("mipnerf360/stump", 4506274),
    52363: ("mipnerf360/treehill", 5073850),
    182686: ("tandt/train", 1257187),
    136029: ("tandt/truck", 2494648),
    80861: ("db/drjohnson", 3613268),
    37005: ("db/playroom", 2237750),
}


def primitive_cap(setting, n_init):
    """Resolve the `max_primitives` config: an int, or "baseline" (table lookup)."""
    if isinstance(setting, bool):
        raise ValueError("max_primitives must be an int or 'baseline'")
    if isinstance(setting, int):
        if setting < n_init:
            raise ValueError("max_primitives is smaller than the initial point count")
        return setting, "config"
    if setting != "baseline":
        raise ValueError("max_primitives must be an int or 'baseline'")
    if n_init not in BASELINE_CAP:
        raise ValueError(
            f"No baseline primitive count for a scene with {n_init} initial points; pass "
            "max_primitives=<int> (Sec. 4.2 sets it to the baseline's final count)"
        )
    scene, cap = BASELINE_CAP[n_init]
    return cap, scene


def ssim_map(image, target, window=11, sigma=1.5):
    """Per-pixel SSIM [H, W] (HWC inputs), 3DGS window (11x11 Gaussian, sigma 1.5), same padding
    (3DGS utils/loss_utils.py `_ssim`), averaged over the RGB channels."""
    coords = torch.arange(window, device=image.device, dtype=image.dtype) - window // 2
    g = torch.exp(-(coords**2) / (2 * sigma**2))
    g = g / g.sum()
    c = image.shape[-1]
    w = (g[:, None] * g[None, :])[None, None].expand(c, 1, window, window).contiguous()
    x, y = (t.permute(2, 0, 1)[None] for t in (image, target))

    def conv(t):
        return F.conv2d(t, w, padding=window // 2, groups=c)

    mx, my = conv(x), conv(y)
    vx, vy, cov = conv(x * x) - mx * mx, conv(y * y) - my * my, conv(x * y) - mx * my
    s = ((2 * mx * my + 0.01**2) * (2 * cov + 0.03**2)) / (
        (mx * mx + my * my + 0.01**2) * (vx + vy + 0.03**2)
    )
    return s[0].mean(dim=0)


def error_map(image, target, kind="ssim"):
    """Auxiliary per-pixel error E_pi(u) (Sec. 3.2), detached: 1 - SSIM(u) or channel-mean l1."""
    with torch.no_grad():
        if kind == "ssim":
            return 1.0 - ssim_map(image, target)
        if kind == "l1":
            return (image - target).abs().mean(dim=-1)
    raise ValueError("error must be 'ssim' or 'l1'")


def corrected_opacity(o):
    """Sec. 3.3: alpha_hat = 1 - sqrt(1 - alpha), solution of (1 - alpha) = (1 - alpha_hat)^2."""
    return 1.0 - torch.sqrt(1.0 - o)


def growth_budget(n, n_max, fraction):
    """Sec. 3.4: new offspring limited to a fraction of the existing primitives and to the
    global cap (each clone or split adds one primitive)."""
    return max(0, min(int(math.floor(fraction * n)), n_max - n))


def select_growth(score, threshold, budget):
    """Sec. 3.2/3.4: candidates score > threshold; if more than the budget, keep the highest."""
    cand = score > threshold
    n_cand = int(cand.sum())
    sel = torch.zeros_like(cand)
    if budget <= 0 or n_cand == 0:
        return sel, n_cand
    if n_cand <= budget:
        return cand, n_cand
    masked = torch.where(cand, score, torch.full_like(score, -float("inf")))
    sel[torch.topk(masked, budget).indices] = True
    return sel, n_cand


def decrement_opacity(o, amount, floor=1e-6):
    """Sec. 3.5: decrease every opacity by a fixed amount after each densification run."""
    return (o - amount).clamp_min(floor)
